import React, { useEffect, useState } from "react";
import MainNav from "../../MainNav/MainNav";
import ArtistManagerNav from "../ArtistManagerNav/ArtistManagerNav";
import "./Applications.css";
import axios from "axios";

const Applications = () => {
  const [pendingArtists, setPendingArtists] = useState([]);
  const [approvedArtists, setApprovedArtists] = useState([]);
  const [rejectedArtists, setRejectedArtists] = useState([]);
  const [loading, setLoading] = useState(true);

  // Fetch all artists
  const fetchApplications = async () => {
    try {
      const res = await axios.get("http://localhost:5000/artists/applications");
      const allArtists = res.data;

      // Split based on status field
      setPendingArtists(allArtists.filter((a) => a.status === "pending"));
      setApprovedArtists(allArtists.filter((a) => a.status === "approved"));
      setRejectedArtists(allArtists.filter((a) => a.status === "rejected"));

      setLoading(false);
    } catch (err) {
      console.error("Error fetching applications:", err);
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchApplications();
  }, []);

  // Approve artist
  const approveArtist = async (id) => {
    try {
      await axios.put(`http://localhost:5000/artists/applications/approve/${id}`);
      alert("Artist approved successfully!");
      fetchApplications(); // refresh lists
    } catch (err) {
      console.error("Error approving artist:", err);
      alert("Failed to approve artist.");
    }
  };

  // Reject artist
  const rejectArtist = async (id) => {
    try {
      await axios.put(`http://localhost:5000/artists/applications/reject/${id}`);
      alert("Artist rejected successfully!");
      fetchApplications(); // refresh lists
    } catch (err) {
      console.error("Error rejecting artist:", err);
      alert("Failed to reject artist.");
    }
  };

  const handleSignOut = () => {
    console.log("Sign out clicked");
  };

  const userName = "Manuth";

  if (loading) return <div>Loading applications...</div>;

  return (
    <div className="dashboard-page">
      <MainNav />

      {/* Dashboard Header */}
      <header className="dashboard-header">
        <div className="dashboard-header-container">
          <div className="dashboard-header-left">
            <h1 className="dashboard-header-title">Artist Manager Dashboard</h1>
            <p className="dashboard-welcome-message">
              Welcome back, {userName}! Manage your artists and applications efficiently.
            </p>
          </div>
          <button className="dashboard-signout-btn" onClick={handleSignOut}>
            <span>Sign Out</span>
          </button>
        </div>
      </header>

      <ArtistManagerNav />

      {/* Pending Applications */}
      <h2>Pending Applications</h2>
      {pendingArtists.length === 0 ? (
        <p>No pending applications.</p>
      ) : (
        <div className="applications-list">
          {pendingArtists.map((artist) => (
            <div className="application-card" key={artist._id}>
              <h3>{artist.stageName}</h3>
              <p>
                Name: {artist.firstName} {artist.lastName}
              </p>
              <p>Email: {artist.email}</p>
              <p>Bio: {artist.bio}</p>
              <div className="application-actions">
                <button
                  onClick={() => approveArtist(artist._id)}
                  className="approve-btn"
                >
                  Approve
                </button>
                <button
                  onClick={() => rejectArtist(artist._id)}
                  className="reject-btn"
                >
                  Reject
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Approved Artists */}
      <h2>Approved Artists</h2>
      {approvedArtists.length === 0 ? (
        <p>No approved artists yet.</p>
      ) : (
        <div className="applications-list">
          {approvedArtists.map((artist) => (
            <div className="application-card approved" key={artist._id}>
              <h3>{artist.stageName}</h3>
              <p>
                Name: {artist.firstName} {artist.lastName}
              </p>
              <p>Email: {artist.email}</p>
              <p>Bio: {artist.bio}</p>
              <span className="approved-label">✅ Approved</span>
            </div>
          ))}
        </div>
      )}

      {/* Rejected Artists */}
      <h2>Rejected Artists</h2>
      {rejectedArtists.length === 0 ? (
        <p>No rejected artists.</p>
      ) : (
        <div className="applications-list">
          {rejectedArtists.map((artist) => (
            <div className="application-card rejected" key={artist._id}>
              <h3>{artist.stageName}</h3>
              <p>
                Name: {artist.firstName} {artist.lastName}
              </p>
              <p>Email: {artist.email}</p>
              <p>Bio: {artist.bio}</p>
              <span className="rejected-label">❌ Rejected</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Applications;
